	private static IEnumerable<mdTypeDef> EnumerateTypeDefsCore(IMetaDataImport instance)
	{
		var handle = default(HCorEnum);
		try
		{
			while (true)
			{
				var hr = instance.EnumTypeDefs(ref handle, out var typeDef, 1, out var count);
				Marshal.ThrowExceptionForHR(hr);
				if (count == 0)
					yield break;
				if (count != 1)
					throw new InvalidOperationException("Native metadata enumerator returned an invalid item count.");
				yield return typeDef;
			}
		}
		finally
		{
			if (!handle.IsNull)
				instance.CloseEnum(handle);
		}
	}

